import { FilesetResolver, TextToSpeech } from '@mediapipe/tasks-audio'

let tts: TextToSpeech | null = null

/**
 * MediaPipe's Emscripten loader normally uses importScripts(), which is not
 * available inside the module workers generated by Vite. Load the pinned
 * loader script explicitly so it registers self.ModuleFactory before the
 * MediaPipe task tries to initialise its WASM runtime.
 */
async function prepareAudioRuntime() {
  const audio = await FilesetResolver.forAudioTasks(
    'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-audio@1.2.2/wasm'
  )
  const fileset = audio as typeof audio & {
    wasmLoaderPath?: string
    assetLoaderPath?: string
  }

  for (const key of ['wasmLoaderPath', 'assetLoaderPath'] as const) {
    const loaderPath = fileset[key]
    if (!loaderPath) continue

    const response = await fetch(loaderPath)
    if (!response.ok) {
      throw new Error(`Could not load MediaPipe runtime (${response.status}).`)
    }

    // Indirect eval executes the Emscripten loader in the worker's global
    // scope, where it defines self.ModuleFactory.
    ;(0, eval)(await response.text())
    delete fileset[key]
  }

  return audio
}

async function createVoiceEngine(delegate: 'GPU' | 'CPU', buffer: ArrayBuffer) {
  // The factory is consumed by MediaPipe during initialisation, so prepare
  // the loader afresh for each attempt (including the CPU fallback).
  const audio = await prepareAudioRuntime()
  return TextToSpeech.createFromOptions(audio, {
    baseOptions: { modelAssetBuffer: new Uint8Array(buffer), delegate },
    defaultVoiceId: 'bm_george',
    defaultLocale: 'en-GB',
    speakingRate: 1.0,
    cacheDirectory: ':nocache'
  })
}

self.onmessage = async (event: MessageEvent) => {
  const { type, id, buffer, text } = event.data || {}
  try {
    if (type === 'init') {
      try {
        tts = await createVoiceEngine('GPU', buffer)
      } catch (gpuError) {
        // GPU/WebGPU is not available on every device. Retry with CPU, but
        // initialise a fresh MediaPipe WASM factory first.
        try {
          tts = await createVoiceEngine('CPU', buffer)
        } catch (cpuError) {
          const message = cpuError instanceof Error ? cpuError.message : String(cpuError)
          throw new Error(`Voice engine could not initialise: ${message}`)
        }
      }
      self.postMessage({ type: 'ready', id })
    } else if (type === 'speak' && tts) {
      const result = await tts.synthesize(String(text || ''))
      const samples = result.samples
      const audioBuffer = samples.slice().buffer as ArrayBuffer
      ;(self as unknown as { postMessage(message: unknown, transfer?: Transferable[]): void }).postMessage({ type: 'audio', id, samples: audioBuffer, sampleRateHz: result.sampleRateHz }, [audioBuffer])
    }
  } catch (error) {
    self.postMessage({ type: 'error', id, message: error instanceof Error ? error.message : String(error) })
  }
}
